add_domain(d, sh_dom); add_lessons(d, sh_lessons)
add_domain(d, mock_domain("Mock Assessment: NICE Framework"))
cap_dom, cap_lessons = capstone_domain(
    "Capstone: Workforce Role Design",
    "Design a complete cybersecurity role (or career plan) using the NICE Framework, documented like a workforce architect.",
    [("Role definition package", "Pick a work role; write the full KSA/task profile plus a job description and interview rubric"),
     ("Team competency map", "Map your team's skills to NICE work roles; identify gaps and a hiring/training plan"),
     ("Career pathway plan", "Chart your 3-year path across NICE categories with certs, projects, and KSA milestones"),
     ("Training curriculum", "Design a 12-week upskilling program mapped to a work role's KSAs with assessments")])
add_domain(d, cap_dom); add_lessons(d, cap_lessons)

def D(did, name, desc, icon):
    dom = {"id": did, "name": name, "description": desc, "icon": icon, "scenarios": []}
    add_domain(d, dom)
    return domain_by_id(d, did)

